function mountFigure6(container,onSelect){
const measures=[
{id:'tBUF',from:'STOP: SMBDAT가 VIH,min을 통과',to:'다음 START: SMBDAT가 VIH,min 아래로 하강',tip:'STOP과 START 사이에 양 선이 HIGH로 유지되는 버스 해제 시간.'},
{id:'tHD:STA',from:'START: SMBDAT가 VIL,max 아래로 하강',to:'SMBCLK가 VIH,min 아래로 하강',tip:'START를 만든 뒤 첫 clock LOW를 시작하기 전까지 확보하는 시간.'},
{id:'tLOW',from:'SMBCLK 하강이 VIL,max를 통과',to:'다음 SMBCLK 상승이 VIL,max를 통과',tip:'유효 LOW 임계값 사이의 clock LOW 폭.'},
{id:'tR',from:'상승 에지: VIL,max − 0.15 V = 0.65 V',to:'상승 에지: VIH,min + 0.15 V = 1.50 V',tip:'Note 7의 마진을 적용한다. 30–70% VDD 측정이 아니다.'},
{id:'tHD:DAT',from:'SMBCLK 하강이 VIL,max를 통과',to:'SMBDAT가 이전 유효 레벨을 벗어나기 시작',tip:'송신 장치가 보장한다. 0 ns여도 클럭이 LOW가 되기 전에 데이터가 바뀌면 안 된다.'},
{id:'tHIGH',from:'SMBCLK 상승이 VIH,min을 통과',to:'다음 하강이 VIH,min을 통과',tip:'HIGH 구간에서 데이터가 안정되어야 한다. 상한은 모든 클래스에서 50 µs.'},
{id:'tF',from:'하강 에지: VIH,min + 0.15 V = 1.50 V',to:'하강 에지: VIL,max − 0.15 V = 0.65 V',tip:'tR과 반대 방향. Table 2 Note 7의 ±150 mV 측정 마진을 사용한다.'},
{id:'tSU:DAT',from:'SMBDAT가 새 유효 레벨에 도달',to:'SMBCLK 상승이 VIL,max에 도달',tip:'다음 clock 상승 전까지 데이터를 안정시켜야 하는 시간.'},
{id:'tSU:STA',from:'SMBCLK 상승이 VIH,min을 통과',to:'repeated START: SMBDAT가 VIH,min 아래로 하강',tip:'STOP을 넣지 않고 새 START를 만드는 조건의 setup 시간.'},
{id:'tSU:STO',from:'SMBCLK 상승이 VIH,min을 통과',to:'STOP: SMBDAT 상승이 VIL,max를 통과',tip:'클럭이 HIGH가 된 다음 데이터를 HIGH로 풀어 STOP을 만든다.'}
];
const events=[
{id:'stop-left',symbol:'P',title:'STOP · 앞선 전송 종료',short:'왼쪽 P · STOP',label:[132,216,12,18],edge:[130,169,16,35],band:407,path:413,transition:'LOW → HIGH',definition:'SMBCLK가 HIGH인 동안 SMBDAT가 LOW에서 HIGH로 바뀌면 STOP 조건입니다.',context:'그림 왼쪽의 P는 앞선 전송의 종료입니다. 그 뒤 첫 S까지의 버스 해제 시간이 tBUF입니다.',related:['tSU:STO','tBUF']},
{id:'start',symbol:'S',title:'START · 전송 시작',short:'첫 S · START',label:[174,216,12,18],edge:[171,169,16,35],band:406,path:415,transition:'HIGH → LOW',definition:'SMBCLK가 HIGH인 동안 SMBDAT가 HIGH에서 LOW로 바뀌면 START 조건입니다.',context:'첫 S는 STOP 이후 버스가 해제된 상태에서 새 전송을 시작합니다. START 뒤 첫 clock LOW까지 tHD:STA를 확보합니다.',related:['tBUF','tHD:STA']},
{id:'restart',symbol:'S',title:'Repeated START · 재시작',short:'두 번째 S · Repeated START',label:[486,216,12,18],edge:[483,169,16,35],band:408,path:446,transition:'HIGH → LOW',definition:'STOP 없이 다시 발생한 START입니다. SMBCLK가 HIGH인 동안 SMBDAT가 HIGH에서 LOW로 바뀌는 조건은 같습니다.',context:'원문 Figure 6은 이 위치도 S로 표기합니다. 첫 START 이후 STOP 없이 이어지므로 repeated START(Sr)입니다. 버스를 해제하지 않고 다시 주소와 R/W를 전송하며, 읽기/쓰기 방향을 바꿀 수도 있습니다.',related:['tSU:STA','tHD:STA']},
{id:'stop-right',symbol:'P',title:'STOP · 현재 전송 종료',short:'오른쪽 P · STOP',label:[692,216,12,18],edge:[690,169,16,35],band:409,path:463,transition:'LOW → HIGH',definition:'SMBCLK가 HIGH인 동안 SMBDAT가 LOW에서 HIGH로 바뀌면 STOP 조건입니다.',context:'오른쪽 P는 현재 전송을 종료합니다. 클럭이 HIGH가 된 뒤 tSU:STO를 확보해 STOP을 만들고, 다음 START까지 tBUF를 확보합니다.',related:['tSU:STO','tBUF']}
];
let active='tLOW',speed=0,activeEvent=null;
// Multiple hit rectangles follow the existing label and arrow, without redrawing either.
const hitRegions={"tBUF":[[149,205,20,16],[142.32,209.96,32.14,8]],"tHD:STA":[[200,154,27,16],[183.64,145.88,16.07,8]],"tLOW":[[222,86,20,17],[208.9,90.96,43.62,8]],"tR":[[260,76,56,16],[252.52,90.96,9.18,8]],"tHD:DAT":[[267,154,27,16],[293.84,145.88,13.85,8]],"tHIGH":[[361,154,20,16],[339.76,145.88,22.96,8]],"tF":[[370,76,56,16],[362.72,90.96,9.18,8]],"tSU:DAT":[[410,151,26,17],[395.25,145.88,13.84,8]],"tSU:STA":[[448,154,26,16],[472.92,145.88,13.77,8]],"tSU:STO":[[654,154,26,16],[679.08,145.88,14.24,8]]};
let drawing=window.SMB_FIGURE6_VECTOR.replace('</svg>','');
// Highlight endpoints share the original PDF measurement-arrow coordinates.
for(const m of measures){const [a,y,w]=hitRegions[m.id][1],b=a+w,arrowY=y+4;
 drawing+=`<g class="f6-range" data-range="${m.id}" visibility="hidden" aria-hidden="true"><rect x="${a}" y="90.3858" width="${w}" height="128.15"/><path d="M${a} 90.3858V218.5358 M${b} 90.3858V218.5358"/><circle cx="${a}" cy="${arrowY}" r="1.3"/><circle cx="${b}" cy="${arrowY}" r="1.3"/></g>`;
}
for(const m of measures){drawing+=`<g class="f6-target" data-measure="${m.id}" tabindex="0" role="button" aria-label="${m.id} 설명과 속도별 스펙 보기" aria-pressed="false"><title>${m.id} — 포인터 / 터치 / Enter로 설명</title>${hitRegions[m.id].map(([x,y,w,h])=>`<rect class="f6-hit" x="${x}" y="${y}" width="${w}" height="${h}" rx="1"/>`).join('')}</g>`;}
for(const e of events){drawing+=`<g class="f6-event-target" data-event="${e.id}" tabindex="0" role="button" aria-label="${e.short} 정의 보기" aria-pressed="false"><title>${e.short} — 정의 보기</title>${[e.label,e.edge].map(([x,y,w,h])=>`<rect class="f6-event-hit" x="${x}" y="${y}" width="${w}" height="${h}" rx="1"/>`).join('')}</g>`;}
drawing+='</svg>';
container.innerHTML=`<section class="lab figure6-lab"><div class="lab-title">스펙 원문 파형에서 찾아보기 <span>FIGURE 6 · p.18</span></div><div class="lab-body"><p class="hint">원문 <b>S/P 표시·데이터 전이</b> 또는 파라미터 이름·측정 화살표에 <b>마우스를 올리세요.</b> 휴대폰에서는 <b>터치</b>하면 설명이 유지됩니다. 좌우로 밀어 전체 파형을 볼 수 있습니다.</p><div class="toolbar"><label>비교 기준<select id="f6-speed"><option>100 kHz</option><option>400 kHz</option><option>1 MHz</option></select></label><label class="zoom-label">파형 확대 <output id="f6-zoom-value">100%</output><input id="f6-zoom" type="range" min="100" max="200" step="25" value="100" aria-label="원문 파형 확대 비율"></label><button class="btn" id="f6-effects" aria-pressed="true">빛 효과 켜짐</button><button class="btn" id="f6-original" aria-haspopup="dialog">원문 그림 보기 ⤢</button></div><div class="figure6-wrap"><div class="f6-scope-header"><div><span class="f6-led"></span> TIMING INSPECTOR <span class="f6-scope-rev">SMBus 3.3 / FIG.06</span></div><div class="f6-scope-legend"><span class="f6-legend-clk">● CLK</span><span class="f6-legend-dat">● DAT</span><span id="f6-scope-selection">파라미터 선택</span></div></div><div id="f6-scroll" tabindex="0" aria-label="전체 타이밍 파형, 좌우 스크롤 가능"><div id="f6-canvas">${drawing}</div></div><div id="f6-tooltip" role="tooltip" hidden></div></div><div class="f6-pills" aria-label="파라미터 바로 선택">${measures.map(m=>`<button class="btn" data-pick="${m.id}">${m.id}</button>`).join('')}</div><div class="f6-event-pills" aria-label="START와 STOP 조건 선택"><span>조건 정의</span>${events.map(e=>`<button class="btn" data-event-pick="${e.id}" aria-pressed="false">${e.short}</button>`).join('')}</div><section id="f6-detail" class="f6-detail" aria-live="polite"></section><p class="hint">출처: SMBus 3.3 Figure 6, p.18 · © 2024 System Management Interface Forum, Inc. — All Rights Reserved. 원문의 선·글자 윤곽을 추출해 사용하고 색상·선택 강조·설명 및 조작 기능을 더했습니다. 원문 그림 보기로 비교할 수 있습니다. 시간축은 비례하지 않습니다. 교차된 두 DAT 선은 가능한 데이터 전이 방향이며 두 개의 물리 신호가 아닙니다. tR/tF는 Note 7의 마진을 적용합니다.</p><button class="btn" id="f6-to-lab">선택 항목을 아래 수치 실험에서 조절 ↓</button></div></section><dialog id="f6-original-dialog" aria-labelledby="f6-original-title"><div class="f6-original-header"><div><h2 id="f6-original-title">Figure 6 · 원문 타이밍 파형</h2><p>SMBus Specification 3.3 · p.18</p></div><button class="btn" id="f6-original-close" autofocus aria-label="원문 그림 닫기">닫기 ×</button></div><div class="f6-original-tools"><button class="btn" id="f6-original-zoom" aria-pressed="false">확대해서 보기</button><span>확대 후 좌우로 밀어 확인하세요.</span></div><div id="f6-original-viewport" tabindex="0" aria-label="원문 Figure 6 이미지, 확대 시 스크롤 가능"><img id="f6-original-image" src="assets/smbus-3.3-figure6.png" width="2225" height="640" alt="SMBus 3.3 Figure 6 원문. SMBCLK와 SMBDAT 파형에 tBUF, tHD:STA, tLOW, tR, tHD:DAT, tHIGH, tF, tSU:DAT, tSU:STA, tSU:STO 측정 구간을 표시한 그림."></div><p class="f6-original-credit">출처: System Management Bus (SMBus) Specification, Version 3.3, 12 May 2024, Figure 6, p.18. © 2024 System Management Interface Forum, Inc. — All Rights Reserved. 원문 그림 영역 발췌(PNG).</p></dialog>`;
const root=container;const find=s=>root.querySelector(s);
let effects=true;try{effects=localStorage.getItem('smbus-figure-effects')!=='off';}catch{}
function setEffects(){find('.figure6-wrap').classList.toggle('f6-quiet',!effects);find('#f6-effects').setAttribute('aria-pressed',String(effects));find('#f6-effects').textContent=effects?'빛 효과 켜짐':'빛 효과 꺼짐';}
find('#f6-effects').onclick=()=>{effects=!effects;setEffects();try{localStorage.setItem('smbus-figure-effects',effects?'on':'off');}catch{}};setEffects();

const original=find('#f6-original-dialog'),originalButton=find('#f6-original'),zoomButton=find('#f6-original-zoom'),viewport=find('#f6-original-viewport');
function resetOriginalZoom(){viewport.classList.remove('zoomed');zoomButton.setAttribute('aria-pressed','false');zoomButton.textContent='확대해서 보기';viewport.scrollLeft=0;viewport.scrollTop=0;}
function closeOriginal(){if(original.close)original.close();else original.removeAttribute('open');originalButton.focus();}
originalButton.onclick=()=>{resetOriginalZoom();if(original.showModal)original.showModal();else original.setAttribute('open','');find('#f6-original-close').focus();};
find('#f6-original-close').onclick=closeOriginal;
original.onclose=()=>originalButton.focus();
original.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeOriginal();}};
original.onclick=e=>{if(e.target===original){const r=original.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeOriginal();}};
zoomButton.onclick=()=>{const enlarged=viewport.classList.toggle('zoomed');zoomButton.setAttribute('aria-pressed',String(enlarged));zoomButton.textContent=enlarged?'전체 그림 맞춤':'확대해서 보기';};
function clearEvent(){activeEvent=null;root.querySelectorAll('[data-event],[data-event-pick]').forEach(e=>{e.classList.remove('selected','primary');e.setAttribute('aria-pressed','false');});root.querySelectorAll('.f6-event-active').forEach(e=>e.classList.remove('f6-event-active'));find('#f6-to-lab').hidden=false;}
function showEvent(id){
 const ev=events.find(e=>e.id===id);clearEvent();activeEvent=id;find('#f6-tooltip').hidden=true;find('#f6-to-lab').hidden=true;
 root.querySelectorAll('[data-measure],[data-pick]').forEach(e=>{e.classList.remove('selected','primary');e.setAttribute('aria-pressed','false');});
 root.querySelectorAll('[data-part]').forEach(e=>e.classList.remove('f6-active'));root.querySelectorAll('[data-range]').forEach(e=>e.setAttribute('visibility','hidden'));
 root.querySelectorAll('[data-event],[data-event-pick]').forEach(e=>{const yes=(e.dataset.event||e.dataset.eventPick)===id;e.classList.toggle(e.dataset.event?'selected':'primary',yes);e.setAttribute('aria-pressed',String(yes));});
 [ev.band,ev.path].forEach(n=>find(`[data-source-path="${n}"]`).classList.add('f6-event-active'));find('#f6-scope-selection').textContent=ev.id==='restart'?'S · Repeated START':ev.symbol+' · '+(ev.symbol==='P'?'STOP':'START');
 find('#f6-detail').innerHTML=`<div><div class="eyebrow">BUS CONDITION · ${ev.symbol}</div><h3>${ev.title}</h3><p><b>${ev.definition}</b></p><p>${ev.context}</p><p class="hint">START·STOP은 Controller가 생성하는 조건이며 데이터 비트가 아닙니다. 일반 데이터 비트는 클럭 HIGH 동안 안정되어야 합니다.</p></div><div>${table(['신호','조건'],[['SMBCLK','HIGH 유지'],['SMBDAT',ev.transition]])}<p class="hint">관련 타이밍 파라미터</p><div class="f6-related">${ev.related.map(p=>`<button class="btn" data-related="${p}">${p}</button>`).join('')}</div><p class="ref"><a href="#link">04장 · 비트·START·ACK →</a><br><a href="${SMB.PDF}#page=27" target="_blank" rel="noopener">원문 §5.1.2 · Figure 11 · p.27 ↗</a></p></div>`;
 root.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{show(b.dataset.related);});
}
function eventTooltip(e,ev){if(e.pointerType==='touch')return;const tip=find('#f6-tooltip'),box=find('.figure6-wrap').getBoundingClientRect();tip.innerHTML=`<b>${ev.title}</b><br>CLK: HIGH 유지<br>DAT: ${ev.transition}<br>${ev.id==='restart'?'STOP 없이 다시 START 발생':'Controller가 생성하는 버스 조건'}<br><small>아래 설명에서 정의·관련 타이밍 확인</small>`;tip.hidden=false;tip.style.left=Math.max(8,Math.min((e.clientX||box.left)-box.left+12,box.width-260))+'px';tip.style.top=Math.max(8,(e.clientY||box.top)-box.top-140)+'px';}
root.querySelectorAll('[data-event]').forEach(g=>{const ev=events.find(e=>e.id===g.dataset.event);g.onpointerenter=e=>{showEvent(ev.id);eventTooltip(e,ev);};g.onpointermove=e=>eventTooltip(e,ev);g.onpointerleave=()=>find('#f6-tooltip').hidden=true;g.onfocus=()=>showEvent(ev.id);g.onclick=()=>showEvent(ev.id);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showEvent(ev.id);}if(e.key==='Escape')find('#f6-tooltip').hidden=true;};});
root.querySelectorAll('[data-event-pick]').forEach(b=>b.onclick=()=>{showEvent(b.dataset.eventPick);const ev=events.find(e=>e.id===activeEvent),scroll=find('#f6-scroll'),canvas=find('#f6-canvas');scroll.scrollLeft=Math.max(0,((ev.label[0]+ev.label[2]/2-63)/667.5)*canvas.getBoundingClientRect().width-scroll.clientWidth/2);});
function show(id,highlight=true){clearEvent();active=id;root.querySelectorAll('[data-part]').forEach(e=>e.classList.toggle('f6-active',highlight&&e.dataset.part===id));root.querySelectorAll('[data-range]').forEach(e=>e.setAttribute('visibility',highlight&&e.dataset.range===id?'visible':'hidden'));find('#f6-scope-selection').textContent=highlight?id:'파라미터 선택';const m=measures.find(m=>m.id===id),p=SMB.timing.find(p=>p.id===id);root.querySelectorAll('[data-measure]').forEach(g=>{const yes=highlight&&g.dataset.measure===id;g.classList.toggle('selected',yes);g.setAttribute('aria-pressed',yes);});root.querySelectorAll('[data-pick]').forEach(b=>{b.classList.toggle('primary',b.dataset.pick===id);b.setAttribute('aria-pressed',b.dataset.pick===id);});find('#f6-detail').innerHTML=`<div><div class="eyebrow">SELECTED PARAMETER</div><h3><code>${id}</code> · ${p.name}</h3><p>${m.tip}</p><div class="f6-endpoints"><div><b>A · 측정 시작</b><span>${m.from}</span></div><div><b>B · 측정 끝</b><span>${m.to}</span></div></div></div><div>${table(['클래스','최소','최대'],['100 kHz','400 kHz','1 MHz'].map((s,i)=>[`${i===speed?'▶ ':''}${s}`,p.min?.[i]==null?'—':p.min[i]+' '+p.unit,p.max?.[i]==null?'—':p.max[i]+' '+p.unit]))}<small>—: 표에 해당 한계 없음 · Table 2 pp.18–20</small></div>`;}
function tooltip(e,id){if(e.pointerType==='touch')return;const p=SMB.timing.find(p=>p.id===id),box=find('.figure6-wrap').getBoundingClientRect(),tip=find('#f6-tooltip');tip.innerHTML=`<b>${id}</b> · ${p.name}<br>${measures.find(m=>m.id===id).tip}<br> ${['100 kHz','400 kHz','1 MHz'][speed]}<br>최소 ${p.min?.[speed]??'—'} / 최대 ${p.max?.[speed]??'—'} ${p.unit}<br><small>아래 설명에서 측정 시작·끝 확인</small>`;tip.hidden=false;tip.style.left=Math.max(8,Math.min((e.clientX||box.left)-box.left+12,box.width-260))+'px';tip.style.top=Math.max(8,(e.clientY||box.top)-box.top-86)+'px';}
root.querySelectorAll('[data-measure]').forEach(g=>{const id=g.dataset.measure;g.onpointerenter=e=>{show(id);tooltip(e,id);};g.onpointermove=e=>tooltip(e,id);g.onpointerleave=()=>find('#f6-tooltip').hidden=true;g.onfocus=()=>show(id);g.onclick=()=>{show(id);find('#f6-tooltip').hidden=true;};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show(id);}if(e.key==='Escape')find('#f6-tooltip').hidden=true;};});
root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{show(b.dataset.pick);const [x,,w]=hitRegions[active][0],scroll=find('#f6-scroll'),canvas=find('#f6-canvas');scroll.scrollLeft=Math.max(0,((x+w/2-63)/667.5)*canvas.getBoundingClientRect().width-scroll.clientWidth/2);});
find('#f6-speed').onchange=e=>{speed=e.target.selectedIndex;find('#f6-tooltip').hidden=true;if(activeEvent)showEvent(activeEvent);else show(active);};find('#f6-zoom').oninput=e=>{const zoom=+e.target.value;find('#f6-zoom-value').textContent=zoom+'%';find('#f6-canvas').style.width=zoom+'%';};find('#f6-to-lab').onclick=()=>onSelect(active,speed);find('#f6-scroll').onscroll=()=>find('#f6-tooltip').hidden=true;show(active,false);
}
